public class Main {
    static int maxProfit(int[] prices) {
        int buy1 = Integer.MIN_VALUE, buy2 = Integer.MIN_VALUE;
        int sell1 = 0, sell2 = 0;
        for (int price : prices) {
            buy1 = Math.max(buy1, -price);                             // best cost of the first buy
            sell1 = Math.max(sell1, buy1 + price);                       // best profit after the first sell
            buy2 = Math.max(buy2, sell1 - price);                          // best net cost of the second buy
            sell2 = Math.max(sell2, buy2 + price);                           // best profit after the second sell
        }
        return sell2;
    }
}

